import jax, jax.numpy as jnp

# Integer/tolerance case
x = jnp.isclose(6, 10, rtol=0.5)
try:
    x_py = bool(x)
except Exception as e:
    x_py = f"EXC:{type(e).__name__}:{e}"

# Key self-comparison: expected to be True after fix; buggy may error or produce wrong bool
key = jax.random.key(0)
try:
    y = jnp.isclose(key, key)
    try:
        y_py = bool(y)
    except Exception as e:
        y_py = f"EXC_BOOL:{type(e).__name__}:{e}"
except Exception as e:
    y_py = f"EXC:{type(e).__name__}:{e}"

# Emit structured probe values
probe('int_case', x_py)
probe('key_case', y_py)

